import java.util.ArrayList;
import java.util.List;

public final class Graph implements IntGraph {
    private final int[][] adjacencyLists;

    private Graph(int[][] adjacencyLists) {
        this.adjacencyLists = adjacencyLists;
    }

    public static Builder builder(int vertexCount) {
        return new Builder(vertexCount);
    }

    @Override
    public int vertexCount() {
        return adjacencyLists.length;
    }

    @Override
    public int neighborCount(int vertex) {
        validateVertex(vertex);
        return adjacencyLists[vertex].length;
    }

    @Override
    public int neighborAt(int vertex, int neighborIndex) {
        validateVertex(vertex);
        if (neighborIndex < 0 || neighborIndex >= adjacencyLists[vertex].length) {
            throw new IllegalArgumentException("neighbor index out of bounds: " + neighborIndex);
        }

        return adjacencyLists[vertex][neighborIndex];
    }

    private void validateVertex(int vertex) {
        if (vertex < 0 || vertex >= adjacencyLists.length) {
            throw new IllegalArgumentException("vertex out of bounds: " + vertex);
        }
    }

    public static final class Builder {
        private final List<List<Integer>> adjacencyLists;

        private Builder(int vertexCount) {
            if (vertexCount < 0) {
                throw new IllegalArgumentException("vertexCount must be non-negative");
            }

            this.adjacencyLists = new ArrayList<>(vertexCount);
            for (int vertex = 0; vertex < vertexCount; vertex++) {
                adjacencyLists.add(new ArrayList<>());
            }
        }

        public Builder addUndirectedEdge(int from, int to) {
            validateVertex(from);
            validateVertex(to);

            adjacencyLists.get(from).add(to);
            adjacencyLists.get(to).add(from);
            return this;
        }

        public Graph build() {
            int[][] packedAdjacencyLists = new int[adjacencyLists.size()][];
            for (int vertex = 0; vertex < adjacencyLists.size(); vertex++) {
                List<Integer> neighbors = adjacencyLists.get(vertex);
                packedAdjacencyLists[vertex] = new int[neighbors.size()];

                for (int index = 0; index < neighbors.size(); index++) {
                    packedAdjacencyLists[vertex][index] = neighbors.get(index);
                }
            }

            return new Graph(packedAdjacencyLists);
        }

        private void validateVertex(int vertex) {
            if (vertex < 0 || vertex >= adjacencyLists.size()) {
                throw new IllegalArgumentException("vertex out of bounds: " + vertex);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Objects;
import java.util.function.IntConsumer;
import java.util.List;

public final class DepthFirstSearch {

    private DepthFirstSearch() {
    }

    public static List<Integer> dfs(IntGraph graph) {
        List<Integer> traversal = new ArrayList<>();
        walk(graph, traversal::add);
        return traversal;
    }

    public static List<Integer> dfsFrom(IntGraph graph, int startVertex) {
        List<Integer> traversal = new ArrayList<>();
        walkFrom(graph, startVertex, traversal::add);
        return traversal;
    }

    public static void walk(IntGraph graph, IntConsumer visitor) {
        new TraversalSession(graph, visitor).traverseAllComponents();
    }

    public static void walkFrom(IntGraph graph, int startVertex, IntConsumer visitor) {
        new TraversalSession(graph, visitor).traverseFrom(startVertex);
    }

    private static final class TraversalSession {
        private final IntGraph graph;
        private final IntConsumer visitor;
        private final boolean[] visited;

        private TraversalSession(IntGraph graph, IntConsumer visitor) {
            this.graph = Objects.requireNonNull(graph, "graph");
            this.visitor = Objects.requireNonNull(visitor, "visitor");
            this.visited = new boolean[graph.vertexCount()];
        }

        private void traverseAllComponents() {
            for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
                if (!visited[vertex]) {
                    traverseComponent(vertex);
                }
            }
        }

        private void traverseFrom(int startVertex) {
            validateVertex(startVertex);
            traverseComponent(startVertex);
        }

        private void traverseComponent(int startVertex) {
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(startVertex);

            while (!stack.isEmpty()) {
                int vertex = stack.pop();
                if (visited[vertex]) {
                    continue;
                }

                visited[vertex] = true;
                visitor.accept(vertex);

                for (int index = graph.neighborCount(vertex) - 1; index >= 0; index--) {
                    int neighbor = graph.neighborAt(vertex, index);
                    if (!visited[neighbor]) {
                        stack.push(neighbor);
                    }
                }
            }
        }

        private void validateVertex(int vertex) {
            if (vertex < 0 || vertex >= visited.length) {
                throw new IllegalArgumentException("vertex out of bounds: " + vertex);
            }
        }
    }
}

public final class Graph implements IntGraph {
    private final int[][] adjacencyLists;

    private Graph(int[][] adjacencyLists) {
        this.adjacencyLists = adjacencyLists;
    }

    public static Builder builder(int vertexCount) {
        return new Builder(vertexCount);
    }

    @Override
    public int vertexCount() {
        return adjacencyLists.length;
    }

    @Override
    public int neighborCount(int vertex) {
        validateVertex(vertex);
        return adjacencyLists[vertex].length;
    }

    @Override
    public int neighborAt(int vertex, int neighborIndex) {
        validateVertex(vertex);
        if (neighborIndex < 0 || neighborIndex >= adjacencyLists[vertex].length) {
            throw new IllegalArgumentException("neighbor index out of bounds: " + neighborIndex);
        }

        return adjacencyLists[vertex][neighborIndex];
    }

    private void validateVertex(int vertex) {
        if (vertex < 0 || vertex >= adjacencyLists.length) {
            throw new IllegalArgumentException("vertex out of bounds: " + vertex);
        }
    }

    public static final class Builder {
        private final IntRowBuilder[] adjacencyLists;

        private Builder(int vertexCount) {
            if (vertexCount < 0) {
                throw new IllegalArgumentException("vertexCount must be non-negative");
            }

            this.adjacencyLists = new IntRowBuilder[vertexCount];
            for (int vertex = 0; vertex < vertexCount; vertex++) {
                adjacencyLists[vertex] = new IntRowBuilder();
            }
        }

        public Builder addDirectedEdge(int from, int to) {
            validateVertex(from);
            validateVertex(to);
            adjacencyLists[from].add(to);
            return this;
        }

        public Builder addUndirectedEdge(int from, int to) {
            return addDirectedEdge(from, to).addDirectedEdge(to, from);
        }

        public Graph build() {
            int[][] packedAdjacencyLists = new int[adjacencyLists.length][];
            for (int vertex = 0; vertex < adjacencyLists.length; vertex++) {
                packedAdjacencyLists[vertex] = adjacencyLists[vertex].toArray();
            }

            return new Graph(packedAdjacencyLists);
        }

        private void validateVertex(int vertex) {
            if (vertex < 0 || vertex >= adjacencyLists.length) {
                throw new IllegalArgumentException("vertex out of bounds: " + vertex);
            }
        }
    }

    private static final class IntRowBuilder {
        private static final int DEFAULT_CAPACITY = 4;

        private int[] values = new int[DEFAULT_CAPACITY];
        private int size;

        private void add(int value) {
            ensureCapacity(size + 1);
            values[size] = value;
            size++;
        }

        private int[] toArray() {
            int[] copy = new int[size];
            System.arraycopy(values, 0, copy, 0, size);
            return copy;
        }

        private void ensureCapacity(int minCapacity) {
            if (minCapacity <= values.length) {
                return;
            }

            int newCapacity = Math.max(minCapacity, values.length * 2);
            int[] expanded = new int[newCapacity];
            System.arraycopy(values, 0, expanded, 0, size);
            values = expanded;
        }
    }
}
